function turnClockwise(grid: number[][]): void {
  const n = grid.length;
  const out = grid.map(row => row.slice());
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++) out[j][n - 1 - i] = grid[i][j];
  for (let i = 0; i < n; i++) grid[i] = out[i];
}

