function turnClockwise(grid: number[][]): void {
  const n = grid.length;
  for (let i = 0; i < n >> 1; i++) {
    for (let j = i; j < n - 1 - i; j++) {
      const top = grid[i][j];
      grid[i][j] = grid[n - 1 - j][i];                 // left → top
      grid[n - 1 - j][i] = grid[n - 1 - i][n - 1 - j]; // bottom → left
      grid[n - 1 - i][n - 1 - j] = grid[j][n - 1 - i]; // right → bottom
      grid[j][n - 1 - i] = top;                        // top → right
    }
  }
}

